/**
 * @file test_network_epoch_contract.cpp
 * @brief The contract of the network epoch (card NOM3 step EP1; generated by scripts/nom_ep1_cut.py from the
 *        canonical table, scripts/nom_ep1/rows_*.py).
 *
 * Compile-time checks, so a failure is a build failure:
 *   - NetworkRun, NetworkRunEngines and NetworkEpoch are neither copyable nor movable, and a
 *     NetworkEpoch cannot be built on a temporary epoch (specification 2.7);
 *   - every converted seam has exactly the parameter list its row states,
 *     (NetworkRun&, const NetworkEpoch&[, kept...][, outputs...]): a seam that starts writing
 *     the epoch must change its row, which regenerates this list (specification 5.9);
 *   - every measure-only row has the observer form NetworkEpochObserver.
 * The explicit overload an adapter keeps is not selected by the casts below (they name the
 * epoch form's type).  The five private member seams are read through
 * NetworkEpochContractProbe, a friend of Application.
 */

#include "app/Application.hpp"
#include "app/NetworkEpoch.hpp"
#include "app/NetworkRun.hpp"
#include "filter/NetworkRunGroups.hpp"
#include "filter/NetworkRunTypes.hpp"
#include "rinex/MultiRinexSync.hpp"

#include <gtest/gtest.h>

#include <type_traits>

namespace GnssProcessor {

/// Reads the private member seams' types (a friend of Application): each member's address
/// converts only to the pointer type its row states.
struct NetworkEpochContractProbe {
    // No member seam is converted at this stage.
};

} // namespace GnssProcessor

namespace {

using namespace GnssProcessor;

// Specification 2.7: the run, its engines and the epoch are neither copyable nor movable,
// and an epoch cannot be built on a temporary.
static_assert(!std::is_copy_constructible_v<NetworkRun> && !std::is_move_constructible_v<NetworkRun>);
static_assert(!std::is_copy_assignable_v<NetworkRun> && !std::is_move_assignable_v<NetworkRun>);
static_assert(!std::is_copy_constructible_v<NetworkRunEngines>
              && !std::is_move_constructible_v<NetworkRunEngines>);
static_assert(!std::is_copy_constructible_v<NetworkEpoch> && !std::is_move_constructible_v<NetworkEpoch>);
static_assert(!std::is_copy_assignable_v<NetworkEpoch> && !std::is_move_assignable_v<NetworkEpoch>);
static_assert(!std::is_constructible_v<NetworkEpoch, SyncedEpoch&&>);
static_assert(std::is_constructible_v<NetworkEpoch, const SyncedEpoch&>);


} // namespace

TEST(NetworkEpochContract, CompiledChecks) {
    // Every check of this file is a static_assert; the case records that it built (0 converted seams).
    SUCCEED();
}
